import { CompilationResult } from '@gram-lang/kitchen';
import { IngredientData, AnalyzedCompilationResult, AnalysisResult } from '@gram-lang/analyzer';

/**
 * Options shared by every pipeline entry point that resolves `@use`
 * specifiers: named aliases from `.gram/config.yaml`'s `paths:`, and the
 * per-run "stock" set of already-resolved module URIs (see
 * `core/stock.ts`'s `resolveStockSet`) — a CLI flag, deliberately never
 * persisted to `.gram/config.yaml`.
 */
interface ModuleResolutionOptions {
    /** Named `@use` specifier aliases (from `.gram/config.yaml`'s `paths:`), threaded to the `ModuleHost` that resolves `@alias/...` specifiers. */
    paths?: Record<string, string>;
    /**
     * `@`-prefixed/relative specifiers, already resolved to module URIs (see
     * `core/stock.ts`'s `resolveStockSet`), the reader already has on hand
     * for this particular build/shop invocation ("stock" mechanism) — a
     * per-run CLI flag, deliberately never persisted to `.gram/config.yaml`.
     */
    stock?: Set<string>;
}
interface PipelineOptions extends ModuleResolutionOptions {
    db?: Record<string, IngredientData> | null;
    skipAnalyzer?: boolean;
    scaleFactor?: number;
    bakersReference?: string;
    bakersMathOnly?: boolean;
    /** Recipe language (from `.gram/config.yaml`'s `language:`), threaded to `analyze()` — see i18n findings F-04/F-07/F-08/F-09. */
    lang?: string;
    /**
     * Shared module-yield measurement cache (module-imports RFC §F.1), keyed
     * by module URI. Pass the *same* Map across a batch of `runPipeline`
     * calls (see `services/builder.ts`) so a base imported by many recipes
     * is compiled+analyzed once, not once per importer. Omitted for a
     * single-file call — `composeRecipe` creates its own throwaway Map.
     */
    moduleCache?: Map<string, AnalyzedCompilationResult>;
}

interface PipelineResult {
    content: string;
    compiled: CompilationResult;
    analyzed: AnalysisResult | null;
    usedStock: Set<string>;
}
/**
 * Every entry point (build/check/shop/scale/view/cook) runs through here,
 * so this is where `@use` imports are resolved -- unconditionally, even for
 * a file with none, so there's exactly one code path rather than a
 * has-imports branch to keep in sync. For a file with no `@use` at all,
 * `loadModuleGraph` does the one file read this function needed anyway and
 * `composeRecipe` is a pass-through (nothing to splice), so this costs
 * nothing extra over the old direct getAST+compile path.
 *
 * `gram import`'s in-memory content (`runPipelineFromSource`, no file path
 * to resolve against) deliberately does NOT go through module resolution --
 * see `prompts/gram-spec.ts`'s own note on why `@use` is never taught to
 * the AI importer.
 */
declare function runPipeline(filePath: string, opts?: PipelineOptions): Promise<PipelineResult>;

declare const ExitCode: {
    readonly Ok: 0;
    readonly Error: 1;
    readonly InternalError: 2;
};
type ExitCode = (typeof ExitCode)[keyof typeof ExitCode];
declare class GramCLIError extends Error {
    readonly exitCode: ExitCode;
    constructor(message: string, exitCode?: ExitCode);
}

export { ExitCode, GramCLIError, type PipelineOptions, type PipelineResult, runPipeline };
